<?php require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/auth.php';if(!setting('external_auth')){unset($_SESSION['otp_challenge'],$_SESSION['otp_subject'],$_SESSION['otp_channel'],$_SESSION['oauth'],$_SESSION['oauth_next']);redirect(current_user()?'khach_hang/ho_so.php':'dang_nhap.php');}$u=require_role(['KHACH_HANG','NHAN_VIEN','ADMIN']);handle_form(function()use($u){throttle('reauth',(string)$u['id'],6,900);must(is_string($_POST['password']??null)&&password_verify($_POST['password'],$u['password']),'Mật khẩu chưa đúng.');$p=$_SESSION['oauth_next']??'';must(in_array($p,['google','facebook'],true),'Không có yêu cầu liên kết.');$_SESSION['reauth_at']=time();redirect('xac_thuc/'.$p.'.php?link=1');},'xac_thuc/xac_thuc_lai.php');page_start('Xác thực lại trước khi liên kết');echo '<div class="auth panel">';token_form();field('password','Mật khẩu hiện tại','','password','required');echo '<button>Tiếp tục</button></form></div>';page_end();
